120	  uint16_t rcvd_num_filters;
121	  uint16_t rcvd_prot_filter_start[BNEP_MAX_PROT_FILTERS];
122	  uint16_t rcvd_prot_filter_end[BNEP_MAX_PROT_FILTERS];
123	
124	  uint16_t rcvd_mcast_filters;
125	  RawAddress rcvd_mcast_filter_start[BNEP_MAX_MULTI_FILTERS];
