60	#define BNEP_SETUP_INVALID_SRC_UUID 0x0002
61	#define BNEP_SETUP_INVALID_UUID_SIZE 0x0003
62	#define BNEP_SETUP_CONN_NOT_ALLOWED 0x0004
63	
