75	/* Timeout definitions.  */
76	/* Connection related timeout */
77	#define BNEP_CONN_TIMEOUT_MS (20 * 1000)
78	/* host response timeout */
79	#define BNEP_HOST_TIMEOUT_MS (200 * 1000)
80	#define BNEP_FILTER_SET_TIMEOUT_MS (10 * 1000)
81	
82	#define BNEP_MAX_RETRANSMITS 3
83	
84	/* Define the BNEP Connection Control Block
85	*/
86	typedef struct {
87	#define BNEP_STATE_IDLE 0
88	#define BNEP_STATE_CONN_START 1
89	#define BNEP_STATE_CFG_SETUP 2
90	#define BNEP_STATE_CONN_SETUP 3
91	#define BNEP_STATE_SEC_CHECKING 4
92	#define BNEP_STATE_SETUP_RCVD 5
93	#define BNEP_STATE_CONNECTED 6
94	  uint8_t con_state;
95	
96	#define BNEP_FLAGS_IS_ORIG 0x01
97	#define BNEP_FLAGS_HIS_CFG_DONE 0x02
98	#define BNEP_FLAGS_MY_CFG_DONE 0x04
99	#define BNEP_FLAGS_L2CAP_CONGESTED 0x08
100	#define BNEP_FLAGS_FILTER_RESP_PEND 0x10
101	#define BNEP_FLAGS_MULTI_RESP_PEND 0x20
102	#define BNEP_FLAGS_SETUP_RCVD 0x40
103	#define BNEP_FLAGS_CONN_COMPLETED 0x80
104	  uint8_t con_flags;
105	  BT_HDR* p_pending_data;
106	
107	  uint16_t l2cap_cid;
108	  RawAddress rem_bda;
109	  alarm_t* conn_timer;
110	  fixed_queue_t* xmit_q;
111	
112	  uint16_t sent_num_filters;
113	  uint16_t sent_prot_filter_start[BNEP_MAX_PROT_FILTERS];
114	  uint16_t sent_prot_filter_end[BNEP_MAX_PROT_FILTERS];
115	
116	  uint16_t sent_mcast_filters;
117	  RawAddress sent_mcast_filter_start[BNEP_MAX_MULTI_FILTERS];
118	  RawAddress sent_mcast_filter_end[BNEP_MAX_MULTI_FILTERS];
119	
120	  uint16_t rcvd_num_filters;
121	  uint16_t rcvd_prot_filter_start[BNEP_MAX_PROT_FILTERS];
