243	static void alarm_set_internal(alarm_t* alarm, uint64_t period_ms,
244	                               alarm_callback_t cb, void* data,
245	                               fixed_queue_t* queue, bool for_msg_loop) {
246	  CHECK(alarms != NULL);
247	  CHECK(alarm != NULL);
248	  CHECK(cb != NULL);
249	
250	  std::lock_guard<std::mutex> lock(alarms_mutex);
251	
252	  alarm->creation_time_ms = now_ms();
253	  alarm->period_ms = period_ms;
254	  alarm->queue = queue;
255	  alarm->callback = cb;
256	  alarm->data = data;
257	  alarm->for_msg_loop = for_msg_loop;
258	
259	  schedule_next_instance(alarm);
260	#ifndef ALARM_DISABLE_STATE
261	  alarm->stats.scheduled_count++;
262	#endif
263	}
