265	void* alarm_cancel(alarm_t* alarm) {
266	  CHECK(alarms != NULL);
267	  void* data;
268	  if (!alarm) return NULL;
269	
270	  std::shared_ptr<std::recursive_mutex> local_mutex_ref;
271	  {
272	    std::lock_guard<std::mutex> lock(alarms_mutex);
273	    local_mutex_ref = alarm->callback_mutex;
274	    data = alarm_cancel_internal(alarm);
275	  }
276	
277	  // If the callback for |alarm| is in progress, wait here until it completes.
278	  std::lock_guard<std::recursive_mutex> lock(*local_mutex_ref);
279	
280	  return data;
281	}
