285	static void* alarm_cancel_internal(alarm_t* alarm) {
286	  bool needs_reschedule =
287	      (!list_is_empty(alarms) && list_front(alarms) == alarm);
288	  void* data = alarm->data;
289	
290	  remove_pending_alarm(alarm);
291	
292	  alarm->deadline_ms = 0;
293	  alarm->prev_deadline_ms = 0;
294	  alarm->callback = NULL;
295	  alarm->data = NULL;
296	#ifndef ALARM_DISABLE_STATE
297	  alarm->stats.canceled_count++;
298	#endif
299	  alarm->queue = NULL;
300	
301	  if (needs_reschedule) reschedule_root_alarm();
302	
303	  return data;
304	}
