612	/*******************************************************************************
613	 *
614	 * Function         bnep_connected
615	 *
616	 * Description      This function is called when a connection is established
617	 *                  (after config).
618	 *
619	 * Returns          void
620	 *
621	 ******************************************************************************/
622	void bnep_connected(tBNEP_CONN* p_bcb) {
623	  bool is_role_change;
624	
625	  if (p_bcb->con_flags & BNEP_FLAGS_CONN_COMPLETED)
626	    is_role_change = true;
627	  else
628	    is_role_change = false;
629	
630	  p_bcb->con_state = BNEP_STATE_CONNECTED;
631	  p_bcb->con_flags |= BNEP_FLAGS_CONN_COMPLETED;
632	  p_bcb->con_flags &= (~BNEP_FLAGS_SETUP_RCVD);
633	
634	  /* Ensure timer is stopped */
635	  alarm_cancel(p_bcb->conn_timer);
636	  p_bcb->re_transmits = 0;
637	
638	  /* Tell the upper layer, if there is a callback */
639	  if (bnep_cb.p_conn_state_cb)
640	    (*bnep_cb.p_conn_state_cb)(p_bcb->handle, p_bcb->rem_bda, BNEP_SUCCESS,
641	                               is_role_change);
642	}
